1	#include "RaylibRenderer.hpp"
2	
3	#include <algorithm>
4	#include <cmath>
5	
6	#include "rlgl.h"
7	
8	#include "DayNight.hpp"
9	#include "Math.hpp"
10	
11	namespace llm_npc {
12	
13	namespace {
14	
15	// Street geometry from City::makeDowntown's documented layout: 3x3 blocks on
16	// a 64-unit pitch, 16-unit streets centered between block edges at ±32.
17	constexpr float kStreetCenter = 32.f;
18	constexpr float kStreetWidth = 16.f;
19	
20	// Ground/asphalt/sidewalk palette — warm, low-poly-friendly flats.
21	constexpr Color kGrass{116, 153, 86, 255};
22	constexpr Color kAsphalt{68, 70, 78, 255};
23	constexpr Color kPlaza{188, 178, 158, 255};
24	constexpr Color kSidewalk{158, 152, 140, 255};
25	
26	// Draws `model` scaled UNIFORMLY to stand `worldHeight` tall, feet on the
27	// ground, centered on (centerX, centerZ) — the Uniform size contract:
28	// the asset keeps its proportions regardless of any collision box.
29	void drawModelUniform(const Model& model, float centerX, float centerZ,
30	                      float worldHeight, Color tint) {
31	    const BoundingBox bb = GetModelBoundingBox(model);
32	    const float h = bb.max.y - bb.min.y;
33	    if (h <= 0.f) return;
34	    const float s = worldHeight / h;
35	    const Vector3 position{centerX - (bb.min.x + bb.max.x) * 0.5f * s,
36	                           -bb.min.y * s,
37	                           centerZ - (bb.min.z + bb.max.z) * 0.5f * s};
38	    DrawModelEx(model, position, Vector3{0.f, 1.f, 0.f}, 0.f, Vector3{s, s, s}, tint);
39	}
40	
41	// Draws `model` scaled and translated so its bounding box exactly fills the
42	// axis-aligned footprint [minX,maxX]x[minZ,maxZ] with the given height,
43	// sitting on the ground plane — the Fill size contract (buildings).
44	// Rotation-free: KayKit city pieces face +Z at identity, which matches the
45	// street-facing fronts of the downtown layout.
46	void drawModelFittedToAABB(const Model& model, float minX, float minZ, float maxX,
47	                           float maxZ, float height, Color tint) {
48	    const BoundingBox bb = GetModelBoundingBox(model);
49	    const Vector3 size{bb.max.x - bb.min.x, bb.max.y - bb.min.y, bb.max.z - bb.min.z};
50	    if (size.x <= 0.f || size.y <= 0.f || size.z <= 0.f) return;
51	    const Vector3 scale{(maxX - minX) / size.x, height / size.y, (maxZ - minZ) / size.z};
52	    const Vector3 position{minX - bb.min.x * scale.x, -bb.min.y * scale.y,
53	                           minZ - bb.min.z * scale.z};
54	    DrawModelEx(model, position, Vector3{0.f, 1.f, 0.f}, 0.f, scale, tint);
55	}
56	
57	// Draws one KayKit road tile (origin-centered 2x2 slab) filling the world
58	// footprint worldX x worldZ at (cx, cz). The Fill scaling happens in model
59	// space, so a 90-degree yaw (X-running streets) swaps which model axis
60	// covers which world axis. Thickness is pinned rather than scaled: a true
61	// 8x fill of the 0.1-thick tile would raise a 0.8-unit curb over the flat
62	// collision plane.
63	void drawRoadTile(const Model& model, float cx, float cz, float worldX,
64	                  float worldZ, bool rotate90) {
65	    const BoundingBox bb = GetModelBoundingBox(model);
66	    const Vector3 size{bb.max.x - bb.min.x, bb.max.y - bb.min.y, bb.max.z - bb.min.z};
67	    if (size.x <= 0.f || size.y <= 0.f || size.z <= 0.f) return;
68	    constexpr float kRoadThickness = 0.05f;
69	    const Vector3 scale{(rotate90 ? worldZ : worldX) / size.x,
70	                        kRoadThickness / size.y,
71	                        (rotate90 ? worldX : worldZ) / size.z};
72	    // Base floats a hair above the grass plane to avoid coplanar flicker.
73	    DrawModelEx(model, Vector3{cx, 0.01f, cz}, Vector3{0.f, 1.f, 0.f},
74	                rotate90 ? 90.f : 0.f, scale, WHITE);
75	}
76	
77	// Composite plaza fountain — the KayKit city pack has no fountain model, so
78	// it is built from primitives on the authored footprint: a stone basin wall,
79	// two smaller tiers, and translucent water discs. `worldHeight` comes from
80	// the fountain's SizeSpec (the single sizing source); radii derive from the
81	// collision AABB so visuals and collider always match.
82	void drawFountain(const Building& b, float worldHeight) {
83	    const float cx = (b.minX + b.maxX) * 0.5f;
84	    const float cz = (b.minZ + b.maxZ) * 0.5f;
85	    const float radius = std::min(b.maxX - b.minX, b.maxZ - b.minZ) * 0.5f;
86	
87	    constexpr Color kStone{172, 168, 156, 255};
88	    constexpr Color kStoneDark{136, 132, 122, 255};
89	    constexpr Color kWater{70, 140, 200, 170};
90	
91	    // Tier proportions (fraction of footprint radius / total height).
92	    const float basinH = worldHeight * 0.25f;
93	    const float midH = worldHeight * 0.50f;
94	    const float topH = worldHeight * 0.25f;
95	
96	    // DrawCylinder renders capped solids, so each "water surface" is a thin
97	    // translucent disc floated just above its stone cap — recessed water
98	    // would be hidden by the cap itself.
99	
100	    // Basin: outer wall filled to the brim with water.
101	    DrawCylinder({cx, 0.f, cz}, radius, radius, basinH, 24, kStone);
102	    DrawCylinderWires({cx, 0.f, cz}, radius, radius, basinH, 24, kStoneDark);
103	    DrawCylinder({cx, basinH, cz}, radius * 0.88f, radius * 0.88f, 0.03f, 24, kWater);
104	
105	    // Middle tier: column carrying a smaller bowl with its own water disc.
106	    DrawCylinder({cx, basinH, cz}, radius * 0.18f, radius * 0.26f, midH, 12, kStone);
107	    DrawCylinder({cx, basinH + midH * 0.7f, cz}, radius * 0.45f, radius * 0.45f,
108	                 midH * 0.3f, 20, kStone);
109	    DrawCylinder({cx, basinH + midH, cz}, radius * 0.38f, radius * 0.38f, 0.03f,
110	                 20, kWater);
111	
112	    // Top spout: a slim finial peaking at exactly worldHeight.
113	    DrawCylinder({cx, basinH + midH, cz}, radius * 0.07f, radius * 0.14f, topH,
114	                 10, kStoneDark);
115	}
116	
117	}  // namespace
118	
119	RaylibRenderer::RaylibRenderer(Assets& assets) : assets_(assets) {}
120	
121	void RaylibRenderer::setTimeOfDay(float hours) {
122	    // Sky, fog, and light all read the same curves from the same clock —
123	    // fog keeps melting distant geometry into the horizon at any hour.
124	    const SkyColor sky = skyColorAt(hours);
125	    skyColor_ = Color{static_cast<unsigned char>(sky.r * 255.f),
126	                      static_cast<unsigned char>(sky.g * 255.f),
127	                      static_cast<unsigned char>(sky.b * 255.f), 255};
128	    lightLevel_ = lightLevelAt(hours);
129	    if (const Shader* fog = assets_.fogShader()) {
130	        const float fogColor[4] = {sky.r, sky.g, sky.b, 1.f};
131	        SetShaderValue(*fog, assets_.fogColorLoc(), fogColor, SHADER_UNIFORM_VEC4);
132	        SetShaderValue(*fog, assets_.fogLightLoc(), &lightLevel_,
133	                       SHADER_UNIFORM_FLOAT);
134	    }
135	}
136	
137	void RaylibRenderer::beginFrame(const CameraPose& pose) {
138	    camera_.position = {pose.position.x, pose.position.y + kEyeHeight, pose.position.z};
139	    // Same authoritative look vector the weapon aims along (issue #91), so the
140	    // crosshair and the shot can never disagree.
141	    const Vec3 dir = lookDirection(pose.yawDeg, pose.pitchDeg);
142	    camera_.target = {camera_.position.x + dir.x, camera_.position.y + dir.y,
143	                      camera_.position.z + dir.z};
144	    camera_.up = {0.f, 1.f, 0.f};
145	    camera_.fovy = 70.f;
146	    camera_.projection = CAMERA_PERSPECTIVE;
147	
148	    // Atmosphere: models carry the fog shader on their materials; wrapping
149	    // the whole 3D pass in BeginShaderMode routes the primitive batch
150	    // (ground plane, slabs, fountain, viewmodel) through the same shader so
151	    // everything hazes consistently. Fog distance needs the camera each
152	    // frame.
153	    if (const Shader* fog = assets_.fogShader()) {
154	        const float eye[3] = {camera_.position.x, camera_.position.y,
155	                              camera_.position.z};
156	        SetShaderValue(*fog, assets_.fogCameraLoc(), eye, SHADER_UNIFORM_VEC3);
157	        BeginMode3D(camera_);
158	        BeginShaderMode(*fog);
159	        return;
160	    }
161	    BeginMode3D(camera_);
162	}
163	
164	void RaylibRenderer::drawCity(const City& city) {
165	    const float half = city.halfSize();
166	
167	    // Ground: grass base with the street grid and block slabs on top.
168	    DrawPlane({0.f, 0.f, 0.f}, {half * 2.f, half * 2.f}, kGrass);
169	
170	    // Streets: KayKit road tiles when the pack is present, flat asphalt
171	    // strips otherwise. Tile pitch = street width (16), centers at multiples
172	    // of 16 so the four junctions at (+-32, +-32) land exactly on tile
173	    // centers; the arm tiles beside each junction (+-16, +-48) carry zebra
174	    // crossings where the sidewalks meet. 13 tiles cover +-104; a compressed
175	    // end-cap tile spans the last 6 units to the +-110 map edge.
176	    const Model* straight = assets_.prop("road_straight");
177	    const Model* crossing = assets_.prop("road_straight_crossing");
178	    const Model* junction = assets_.prop("road_junction");
179	    if (straight && crossing && junction) {
180	        constexpr float kTile = 16.f;
181	        for (const float sc : {-kStreetCenter, kStreetCenter}) {
182	            for (float t = -96.f; t <= 96.f; t += kTile) {
183	                if (t == -kStreetCenter || t == kStreetCenter) {
184	                    // Both streets pass through this tile; draw the 4-way
185	                    // junction art once (in the Z-running pass).
186	                    drawRoadTile(*junction, sc, t, kStreetWidth, kTile, false);
187	                    continue;
188	                }
189	                const float arm = std::fabs(std::fabs(t) - kStreetCenter);
190	                const Model& tile = (arm == kTile) ? *crossing : *straight;
191	                drawRoadTile(tile, sc, t, kStreetWidth, kTile, false);
192	                drawRoadTile(tile, t, sc, kTile, kStreetWidth, true);
193	            }
194	            for (const float e : {-107.f, 107.f}) {
195	                drawRoadTile(*straight, sc, e, kStreetWidth, 6.f, false);
196	                drawRoadTile(*straight, e, sc, 6.f, kStreetWidth, true);
197	            }
198	        }
199	    } else {
200	        for (const float c : {-kStreetCenter, kStreetCenter}) {
201	            DrawCube({c, 0.02f, 0.f}, kStreetWidth, 0.04f, half * 2.f, kAsphalt);
202	            DrawCube({0.f, 0.02f, c}, half * 2.f, 0.04f, kStreetWidth, kAsphalt);
203	        }
204	    }
205	    // Block slabs: plaza (center) is pale stone, park (north-east) stays
206	    // grass, every other block gets a sidewalk-toned slab.
207	    for (const float bx : {-64.f, 0.f, 64.f}) {
208	        for (const float bz : {-64.f, 0.f, 64.f}) {
209	            const bool plaza = bx == 0.f && bz == 0.f;
210	            const bool park = bx == 64.f && bz == 64.f;
211	            if (park) continue;
212	            DrawCube({bx, 0.04f, bz}, 48.f, 0.08f, 48.f, plaza ? kPlaza : kSidewalk);
213	        }
214	    }
215	
216	    // Street furniture (traffic lights, bushes) renders through the same
217	    // buildings pass below — City authors their positions AND colliders,
218	    // so nothing visible can be walk-through.
219	
220	    // Buildings and street props from the collision AABBs — the models scale
221	    // to fit the authoritative footprints, never the other way around.
222	    for (const Building& b : city.buildings()) {
223	        // The fountain is composed from primitives (no pack model). Must be
224	        // dispatched by id BEFORE the model lookup: modelForBuilding falls
225	        // back to a hashed generic building for uncurated ids.
226	        if (b.id == "fountain") {
227	            drawFountain(b, assets_.sizeSpecFor(b).worldHeight);
228	            continue;
229	        }
230	        if (const Model* model = assets_.modelForBuilding(b)) {
231	            const Assets::SizeSpec& spec = assets_.sizeSpecFor(b);
232	            if (spec.mode == Assets::SizeSpec::Mode::Uniform) {
233	                drawModelUniform(*model, (b.minX + b.maxX) * 0.5f,
234	                                 (b.minZ + b.maxZ) * 0.5f, spec.worldHeight, WHITE);
235	            } else {
236	                drawModelFittedToAABB(*model, b.minX, b.minZ, b.maxX, b.maxZ, b.height,
237	                                      WHITE);
238	            }
239	        } else {
240	            // Fallback primitive, tinted like the legacy renderer's boxes.
241	            const unsigned char tint =
242	                static_cast<unsigned char>(120 + (b.facadeKind * 37) % 90);
243	            const Vector3 center{(b.minX + b.maxX) * 0.5f, b.height * 0.5f,
244	                                 (b.minZ + b.maxZ) * 0.5f};
245	            DrawCube(center, b.maxX - b.minX, b.height, b.maxZ - b.minZ,
246	                     Color{tint, tint, static_cast<unsigned char>(tint + 20), 255});
247	            DrawCubeWires(center, b.maxX - b.minX, b.height, b.maxZ - b.minZ,
248	                          Color{40, 45, 60, 255});
249	        }
250	    }
251	}
252	
253	void RaylibRenderer::drawCharacter(const CharacterVisual& visual) {
254	    const Assets::CharacterAsset* character =
255	        assets_.characterFor(visual.variantSeed, visual.police);
256	    if (!character) {
257	        // No pack: marker cylinder, same as the pre-asset placeholder.
258	        const Vec3& p = visual.position;
259	        DrawCylinder({p.x, 0.f, p.z}, 0.35f, 0.35f, 1.8f, 12, Color{200, 120, 80, 255});
260	        DrawCylinderWires({p.x, 0.f, p.z}, 0.35f, 0.35f, 1.8f, 12, Color{60, 30, 20, 255});
261	        return;
262	    }
263	
264	    // Pick the clip: death overrides everything, gestures interrupt,
265	    // then walk/idle by movement.
266	    int clip = visual.walking ? character->walk : character->idle;
267	    if (visual.gesturePhase > 0.f && character->gesture >= 0) clip = character->gesture;
268	    if (visual.dead && character->death >= 0) clip = character->death;
269	
270	    AnimState& state = anim_[visual.variantSeed];
271	    if (state.clip != clip) {
272	        state.clip = clip;
273	        state.time = 0.f;
274	    }
275	    state.time += GetFrameTime();
276	    if (clip >= 0 && clip < character->clipCount) {
277	        // raylib bakes glTF animations at ~60 samples/second; loop by frame.
278	        const ModelAnimation& animation = character->clips[clip];
279	        const int frame =
280	            static_cast<int>(state.time * 60.f) % (animation.frameCount > 0
281	                                                       ? animation.frameCount
282	                                                       : 1);
283	        // CPU skinning on the shared model right before this entity's draw,
284	        // so several entities can reuse one model with different clocks.
285	        UpdateModelAnimation(character->model, animation, frame);
286	    }
287	
288	    // Uniform height: scale so every character stands ~1.8 units tall, feet
289	    // on the ground, rotated to the game's facing convention (0 → +Z).
290	    const BoundingBox bb = GetModelBoundingBox(character->model);
291	    const float modelHeight = bb.max.y - bb.min.y;
292	    const float s = modelHeight > 0.f ? 1.8f / modelHeight : 1.f;
293	    const Vector3 position{visual.position.x, -bb.min.y * s, visual.position.z};
294	    DrawModelEx(character->model, position, Vector3{0.f, 1.f, 0.f}, visual.facingDeg,
295	                Vector3{s, s, s}, WHITE);
296	
297	    // Non-neutral moods float as an emote above the head — the same six
298	    // procedural faces the legacy renderer painted on, now billboarded.
299	    // The dead don't emote.
300	    if (!visual.dead && visual.face != NpcFace::Neutral) {
301	        DrawBillboard(camera_, assets_.faceTexture(visual.face),
302	                      Vector3{visual.position.x, 2.45f, visual.position.z}, 0.55f,
303	                      WHITE);
304	    }
305	}
306	
307	void RaylibRenderer::drawCompositeCharacter(const CharacterLook& look,
308	                                            const Vec3& position, float facingDeg,
309	                                            bool walking, float phase) {
310	    const AssembledLook assembled = assembleLook(look);
311	    if (!assembled.ok) {
312	        // Invalid/stale look: the same marker cylinder the pack path uses.
313	        DrawCylinder({position.x, 0.f, position.z}, 0.35f, 0.35f, 1.8f, 12,
314	                     Color{200, 120, 80, 255});
315	        return;
316	    }
317	    // ONE uniform scale takes the whole assembly to the same height
318	    // contract pack characters use — parts were snapped in local space, so
319	    // proportions and socket alignment survive any future contract change.
320	    const float s = 1.8f / assembled.height;
321	
322	    const PartPalette* palette = &paletteCatalog().front();
323	    for (const PartPalette& candidate : paletteCatalog()) {
324	        if (candidate.id == look.paletteId) palette = &candidate;
325	    }
326	    const Color skin{palette->skin[0], palette->skin[1], palette->skin[2], 255};
327	    const Color hair{palette->hair[0], palette->hair[1], palette->hair[2], 255};
328	    const Color outfit{palette->outfit[0], palette->outfit[1], palette->outfit[2], 255};
329	    const Color dark{38, 38, 44, 255};
330	
331	    // Whole-figure transform: facing + procedural walk bob. Parts then draw
332	    // at their assembly-local positions and rotate correctly for free.
333	    const float bob = walking ? std::fabs(std::sin(phase * 7.f)) * 0.05f : 0.f;
334	    rlPushMatrix();
335	    rlTranslatef(position.x, position.y + bob, position.z);
336	    rlRotatef(facingDeg, 0.f, 1.f, 0.f);
337	
338	    for (const PlacedPart& placed : assembled.parts) {
339	        const PartDef& part = *placed.part;
340	        const Vec3 at = placed.position * s;          // anchor, bottom-center
341	        const Vec3 dim = part.localSize * s;
342	        const float cy = at.y + dim.y * 0.5f;         // box center height
343	
344	        if (part.id == "body_round") {
345	            // Tapered trunk: narrow shoulders over a wider base.
346	            DrawCylinder({at.x, at.y, at.z}, dim.x * 0.34f, dim.x * 0.5f,
347	                         dim.y, 16, outfit);
348	        } else if (part.id == "head_round") {
349	            DrawSphere({at.x, cy, at.z}, dim.y * 0.5f, skin);
350	        } else if (part.id == "hair_tuft") {
351	            DrawSphere({at.x, at.y + dim.y * 0.3f, at.z}, dim.x * 0.5f, hair);
352	        } else if (part.id == "hair_bowl") {
353	            // Oversized cap sunk into the head reads as a bowl cut.
354	            DrawSphere({at.x, at.y - dim.y * 0.55f, at.z}, dim.x * 0.5f, hair);
355	        } else if (part.id == "hair_spikes") {
356	            for (int i = -1; i <= 1; ++i) {
357	                DrawCylinder({at.x + static_cast<float>(i) * dim.x * 0.30f,
358	                              at.y - dim.y * 0.25f, at.z},
359	                             0.f, dim.x * 0.16f, dim.y, 8, hair);
360	            }
361	        } else if (part.id == "body_slim") {
362	            // Slimmer tapered trunk than body_round (issue #92).
363	            DrawCylinder({at.x, at.y, at.z}, dim.x * 0.30f, dim.x * 0.42f,
364	                         dim.y, 16, outfit);
365	        } else if (part.id == "head_oval") {
366	            // Vertically stretched sphere reads as a longer, oval face.
367	            rlPushMatrix();
368	            rlTranslatef(at.x, cy, at.z);
369	            rlScalef(1.f, dim.y / dim.x, 1.f);
370	            DrawSphere({0.f, 0.f, 0.f}, dim.x * 0.5f, skin);
371	            rlPopMatrix();
372	        } else if (part.id == "hair_pony") {
373	            // A rounded cap plus a small tail behind the head.
374	            DrawSphere({at.x, at.y + dim.y * 0.30f, at.z}, dim.x * 0.5f, hair);
375	            DrawSphere({at.x, at.y - dim.y * 0.10f, at.z - dim.z * 0.5f},
376	                       dim.x * 0.34f, hair);
377	        } else if (part.id == "hair_mohawk") {
378	            // A single tall narrow crest running front-to-back.
379	            DrawCube({at.x, cy, at.z}, dim.x * 0.5f, dim.y, dim.z, hair);
380	        } else if (part.category == PartCategory::Eyes) {
381	            if (part.id == "eyes_visor") {
382	                DrawCube({at.x, cy, at.z}, dim.x, dim.y, dim.z, dark);
383	            } else {
384	                // Two pupils split across the part's declared width.
385	                const float dx = dim.x * 0.5f - dim.y * 0.5f;
386	                DrawSphere({at.x - dx, cy, at.z}, dim.y * 0.5f, dark);
387	                DrawSphere({at.x + dx, cy, at.z}, dim.y * 0.5f, dark);
388	            }
389	        } else if (part.localSize.y > 0.f) {
390	            // Generic recipe: any part without a bespoke shape renders as
391	            // its declared box (skin for heads, hair on top, outfit below)
392	            // so NEW catalog parts appear immediately, just plainly.
393	            const Color color = part.category == PartCategory::Head ? skin
394	                                : part.category == PartCategory::Hair ? hair
395	                                                                      : outfit;
396	            DrawCube({at.x, cy, at.z}, dim.x, dim.y, dim.z, color);
397	        }
398	    }
399	    rlPopMatrix();
400	}
401	
402	void RaylibRenderer::drawViewmodel(int weaponKind, float attackFraction) {
403	    // Per-weapon visuals live in this table; adding a WeaponKind means
404	    // adding a row, never a new code branch. Sizes are camera-space meters.
405	    struct ViewSpec {
406	        Vector3 size;        // main body (fist / gun body)
407	        Color color;
408	        float thrust;        // + pushes forward on attack (punch), - recoils
409	        bool grip;           // draw a pistol-style grip under the body
410	    };
411	    static const ViewSpec kSpecs[] = {
412	        {{0.11f, 0.09f, 0.14f}, Color{224, 172, 138, 255}, 0.45f, false},  // Fist
413	        {{0.05f, 0.07f, 0.30f}, Color{55, 58, 66, 255}, -0.14f, true},     // Pistol
414	    };
415	    const int count = static_cast<int>(sizeof(kSpecs) / sizeof(kSpecs[0]));
416	    if (weaponKind < 0 || weaponKind >= count) return;
417	    const ViewSpec& spec = kSpecs[weaponKind];
418	
419	    // Camera basis for a lower-right anchored prop.
420	    const Vector3 fwd{camera_.target.x - camera_.position.x,
421	                      camera_.target.y - camera_.position.y,
422	                      camera_.target.z - camera_.position.z};
423	    const float flen = std::sqrt(fwd.x * fwd.x + fwd.y * fwd.y + fwd.z * fwd.z);
424	    if (flen < 1e-4f) return;
425	    const Vector3 f{fwd.x / flen, fwd.y / flen, fwd.z / flen};
426	    // Same right-vector convention as the game's strafe (flatRight in
427	    // main.cpp): cross(forward, up) = (-fz, 0, fx).
428	    const Vector3 r{-f.z, 0.f, f.x};
429	
430	    const float push = spec.thrust * attackFraction;
431	    const Vector3 base{
432	        camera_.position.x + f.x * (0.85f + push) + r.x * 0.32f,
433	        camera_.position.y - 0.28f + f.y * (0.85f + push),
434	        camera_.position.z + f.z * (0.85f + push) + r.z * 0.32f};
435	
436	    DrawCubeV(base, spec.size, spec.color);
437	    if (spec.grip) {
438	        DrawCubeV(Vector3{base.x - f.x * 0.10f, base.y - 0.07f, base.z - f.z * 0.10f},
439	                  Vector3{0.045f, 0.10f, 0.06f}, spec.color);
440	    }
441	}
442	
443	void RaylibRenderer::endFrame() {
444	    if (assets_.fogShader()) EndShaderMode();
445	    EndMode3D();
446	}
447	
448	bool RaylibRenderer::worldToScreen(const Vec3& world, Vector2& out) const {
449	    // Reject points behind the camera: GetWorldToScreen would mirror them.
450	    const Vector3 toPoint{world.x - camera_.position.x, world.y - camera_.position.y,
451	                          world.z - camera_.position.z};
452	    const Vector3 forward{camera_.target.x - camera_.position.x,
453	                          camera_.target.y - camera_.position.y,
454	                          camera_.target.z - camera_.position.z};
455	    if (toPoint.x * forward.x + toPoint.y * forward.y + toPoint.z * forward.z <= 0.f) {
456	        return false;
457	    }
458	    out = GetWorldToScreen({world.x, world.y, world.z}, camera_);
459	    return true;
460	}
