171	    // children), each child at parent anchor + parent's declared socket.
172	    Vec3 anchors[kPartCategoryCount];
173	    for (const CategorySpec& spec : categorySpecs()) {
174	        const int c = static_cast<int>(spec.category);
175	        const PartDef* part = findPart(look.partIds[c]);
176	        if (spec.socket[0] == '\0') {
177	            anchors[c] = Vec3{};  // root sits on the ground at the origin
178	        } else {
179	            const int p = static_cast<int>(spec.parent);
180	            const PartDef* parent = findPart(look.partIds[p]);
181	            const auto socket = parent->sockets.find(spec.socket);
182	            if (socket == parent->sockets.end()) {
183	                out.error = parent->id + " has no '" + spec.socket + "' socket";
184	                return out;
185	            }
186	            anchors[c] = anchors[p] + socket->second;
187	        }
188	        out.parts.push_back({part, anchors[c]});
189	        out.height = std::max(out.height, anchors[c].y + part->localSize.y);
190	    }
191	    out.ok = out.height > 0.f;
192	    if (!out.ok) out.error = "assembled look has no height";
193	    return out;
194	}
