196	CharacterLook randomizeLook(unsigned seed) {
197	    Rng rng{seed ? seed : 1u};  // xorshift can't start at 0
198	    CharacterLook look;
199	
200	    // Body first — it sets the style family the other picks must match.
201	    const auto bodies = partsForCategory(PartCategory::Body, "any");
202	    const PartDef* body = bodies[rng.pick(bodies.size())];
203	    look.part(PartCategory::Body) = body->id;
204	    for (const CategorySpec& spec : categorySpecs()) {
205	        if (spec.category == PartCategory::Body) continue;
206	        const auto options = partsForCategory(spec.category, body->styleTag);
207	        look.part(spec.category) = options[rng.pick(options.size())]->id;
208	    }
209	    const auto& palettes = paletteCatalog();
210	    look.paletteId = palettes[rng.pick(palettes.size())].id;
211	    return look;
212	}
