214	std::string CharacterLook::toJson() const {
215	    nlohmann::json j;
216	    j["body"] = part(PartCategory::Body);
217	    j["head"] = part(PartCategory::Head);
218	    j["eyes"] = part(PartCategory::Eyes);
219	    j["hair"] = part(PartCategory::Hair);
220	    j["palette"] = paletteId;
221	    return j.dump();
222	}
