224	bool CharacterLook::fromJson(const std::string& json, CharacterLook& out) {
225	    const nlohmann::json j = nlohmann::json::parse(json, nullptr, false);
226	    if (!j.is_object()) return false;
227	    const char* keys[kPartCategoryCount] = {"body", "head", "eyes", "hair"};
228	    for (int c = 0; c < kPartCategoryCount; ++c) {
229	        if (!j.contains(keys[c]) || !j[keys[c]].is_string()) return false;
230	        out.partIds[c] = j[keys[c]].get<std::string>();
231	    }
232	    if (!j.contains("palette") || !j["palette"].is_string()) return false;
233	    out.paletteId = j["palette"].get<std::string>();
234	    return true;
235	}
